{
  "bioavailability_prediction": "high",
  "claims": [
    {
      "card_ids": ["C02"],
      "claim": "Saxagliptin, which contains an adamantane core and a primary amine-bearing substituent, has an absolute oral bioavailability of 50% (48–53%) in healthy volunteers when measured against an intravenous microdose, supporting high oral bioavailability for the similarly small adamantane amine query.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C03"],
      "claim": "Mecamylamine, a small basic bicyclic amine, was reported to have complete oral bioavailability in healthy subjects, supporting high F for the query's small, basic, lipophilic amine structure.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C16"],
      "claim": "Phenylpropanolamine, a small ionizable primary amine, had an absolute oral bioavailability of about 62% in healthy volunteers, indicating that small basic amines can be well absorbed orally despite ionization.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C14"],
      "claim": "Alafosfalin, a small amino-containing drug, showed approximately 50% oral bioavailability in humans, providing additional supportive evidence that small polar amines can exceed the 20% threshold.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C06"],
      "claim": "Cyclandelate showed extremely low oral bioavailability from capsules in humans, but this is a structurally distant ester with formulation-dependent absorption and does not transfer meaningfully to the adamantane amine query.",
      "evidence_role": "contradictory"
    }
  ],
  "confidence": "moderate",
  "decision_summary": "Predicted high: the query is a small, lipophilic adamantane primary amine. The most relevant human data—saxagliptin (50% F), mecamylamine (complete), phenylpropanolamine (~62%), and alafosfalin (~50%)—consistently show oral bioavailability well above 20% for small basic amines and adamantane-containing drugs. The one low-bioavailability analogue is structurally distant and formulation-specific, so it does not overturn the supportive pattern.",
  "evidence_gaps": [
    "No direct absolute oral bioavailability measurement for rimantadine itself is included in the provided evidence.",
    "Morgan similarities between the query and the evidence molecules are low (0.14–0.24), limiting quantitative transferability.",
    "Metabolic stability and first-pass extraction for the query are not directly measured in the provided records."
  ],
  "new_evidence_assessment": [],
  "revision_action": "initial"
}

